initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing an initial Entity ${entity} 
        with an id set to ${entityId} 
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Append Entity Attributes With Parameters with Response Status Code set to 204     and
        ${expectation_filename} with Check Response Body Content and
            Query Parameter: expectation_filename set to 'expectation_response_body' and
            Query Parameter: response_body set to '' and
            Query Parameter: additional_ignored_path set to 'root\\['notUpdated'\\]\\[0\\]\\['reason'\\]'     and
        Retrieve Entity by Id with Updated Entity set to ${entity}
}

then {
    the SUT sends a valid Response for the operations:
        Append Entity Attributes With Parameters with Response Status Code set to 204     and
        ${expectation_filename} with Check Response Body Content and
            Query Parameter: expectation_filename set to 'expectation_response_body' and
            Query Parameter: response_body set to '' and
            Query Parameter: additional_ignored_path set to 'root\\['notUpdated'\\]\\[0\\]\\['reason'\\]'     and
        Retrieve Entity by Id with Updated Entity set to ${entity}
}
